// Existing production table shape used by isolated SQL tests.
export const portfolioSchema = owner => `create role anon; create role authenticated; create schema auth; create table auth.users(id uuid primary key); insert into auth.users values('${owner}'),('00000000-0000-4000-8000-000000000002'); create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$; grant usage on schema auth to authenticated; grant execute on function auth.uid() to authenticated;
 create table public.portfolio_transactions(id uuid primary key,user_id uuid not null references auth.users,symbol text not null,name text not null,transaction_type text not null check(transaction_type in ('buy','sell')),trade_date date not null,quantity numeric not null check(quantity>0),price numeric not null check(price>0),fee numeric not null default 0 check(fee>=0),currency text,fx_rate_to_krw numeric,usd_krw_rate_at_transaction numeric,created_at timestamptz not null default now());
 create table public.portfolio_preferences(user_id uuid primary key references auth.users,display_currency text not null default 'KRW',updated_at timestamptz not null default now(),portfolio_started_at timestamptz,snapshot_cutoff_time time not null default '23:59:59',snapshot_timezone text not null default 'Asia/Seoul');
 create table public.portfolio_snapshots(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users,snapshot_date date not null,cutoff_at timestamptz not null,captured_at timestamptz not null default now(),portfolio_started_at timestamptz not null,total_assets_krw numeric not null check(total_assets_krw>=0),investment_assets_krw numeric not null check(investment_assets_krw>=0),cash_assets_krw numeric not null default 0,twr_index numeric not null default 100,net_flow_krw numeric not null default 0,cumulative_net_flow_krw numeric not null default 0,cumulative_profit_krw numeric not null default 0,is_active boolean not null default false,is_final boolean not null default false,valuation_method text not null default 'reconstructed_daily_close',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,snapshot_date));`;
